package com.bank.jenkins;

import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.Logger;

// Simulates Jenkins Kubernetes plugin: a pod is created per build, then released.
public class AgentPool {
    private static final Logger log = Logger.getLogger(AgentPool.class.getName());
    private final AtomicInteger livePods = new AtomicInteger();

    public String acquirePod(String label) {
        String pod = "jenkins-agent-" + label + "-" + livePods.incrementAndGet();
        log.info(() -> "K8s API: created pod " + pod + " (live pods=" + livePods.get() + ")");
        return pod;
    }

    public void releasePod(String pod) {
        log.info(() -> "K8s API: deleted pod " + pod + " (live pods=" + livePods.decrementAndGet() + ")");
    }
}
