package com.bank.jenkins;

import java.util.logging.Logger;

// CI: triggered on push. Builds, tests, scans, publishes an immutable artifact.
public class CiPipeline {
    private static final Logger log = Logger.getLogger(CiPipeline.class.getName());
    private final AgentPool agentPool;

    public CiPipeline(AgentPool agentPool) { this.agentPool = agentPool; }

    public Artifact onPush(String service, String commitSha) {
        String pod = agentPool.acquirePod("ci");
        try {
            log.info(() -> "[CI] " + pod + " mvn clean package");
            log.info(() -> "[CI] " + pod + " mvn test -> 42 passed");
            log.info(() -> "[CI] " + pod + " trivy scan -> clean");
            Artifact artifact = new Artifact(service, commitSha);
            log.info(() -> "[CI] published " + artifact.getImageTag());
            return artifact;
        } finally {
            agentPool.releasePod(pod); // pod destroyed after build
        }
    }
}
