package com.bank.jenkins;

// Models the Jenkins `input` step: production needs an approver.
public class ApprovalGate {
    private final java.util.Set<String> releaseManagers;

    public ApprovalGate(java.util.Set<String> releaseManagers) {
        this.releaseManagers = releaseManagers;
    }

    // Returns true only if the approver is an authorised release manager.
    public boolean approve(String approver) {
        return releaseManagers.contains(approver);
    }
}
