package com.bank.jenkins;

import java.util.logging.Logger;

// CD: triggered by CI success. Promotes the SAME artifact through environments.
public class CdPipeline {
    private static final Logger log = Logger.getLogger(CdPipeline.class.getName());
    private final AgentPool agentPool;
    private final ApprovalGate gate;

    public CdPipeline(AgentPool agentPool, ApprovalGate gate) {
        this.agentPool = agentPool;
        this.gate = gate;
    }

    public boolean promote(Artifact artifact, String prodApprover) {
        String pod = agentPool.acquirePod("cd");
        try {
            deploy(pod, artifact, "dev");   // automatic
            deploy(pod, artifact, "qa");    // automatic
            if (!gate.approve(prodApprover)) {
                log.severe("[CD] Production approval DENIED for approver '" + prodApprover + "'");
                return false;
            }
            log.info(() -> "[CD] Production approved by " + prodApprover);
            deploy(pod, artifact, "prod");  // only after approval
            return true;
        } finally {
            agentPool.releasePod(pod);
        }
    }

    private void deploy(String pod, Artifact a, String env) {
        log.info(() -> "[CD] " + pod + " kubectl set image deploy/" + a.getService()
                + " =" + a.getImageTag() + " --namespace " + env);
    }
}
