package com.bank.jenkins;

import java.util.Set;
import java.util.logging.*;

public class JenkinsDemo {
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new JenkinsLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AgentPool pool = new AgentPool();
        ApprovalGate gate = new ApprovalGate(Set.of("priya-release-mgr"));

        // CI runs on push, producing one immutable artifact.
        CiPipeline ci = new CiPipeline(pool);
        Artifact artifact = ci.onPush("transfer-service", "a1b2c3d4");

        // CD promotes the SAME artifact. First an unauthorised approver is blocked.
        CdPipeline cd = new CdPipeline(pool, gate);
        cd.promote(artifact, "rajesh-dev");        // denied at prod gate
        cd.promote(artifact, "priya-release-mgr"); // approved -> reaches prod
    }
}

